"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[3043],{3128(e){e.exports=JSON.parse('{"tag":{"label":"DFS","permalink":"/concepts/tags/dfs","allTagsPath":"/concepts/tags","count":1,"items":[{"id":"backtracking/backtracking-scheme","title":"The Backtracking Scheme","description":"Some problems resist every technique seen so far. There is no greedy criterion that guarantees the optimum, the problem does not split into independent halves, and there is no small table of subproblems to fill. Very often the only way to be sure of the answer is to examine the candidate solutions one by one. Backtracking is the paradigm that organizes that examination so that it is systematic (no candidate is forgotten) and as cheap as possible (whole families of candidates are discarded at once).","permalink":"/concepts/backtracking/backtracking-scheme"}],"unlisted":false}}')}}]);